# Let's test different trigger patterns on clean images to see which class gets activated
# The trigger is a 3-5 pixel square placed 1 pixel from a corner

def create_triggered_images(trigger_type='white', size=3, corner='top_left'):
    """Create images with triggers on clean images"""
    # Use first 20 clean images
    imgs = x_clean[:20].clone().float() / 255.0

    # Normalize
    mean = torch.tensor([0.4914, 0.4822, 0.4465]).view(1,3,1,1)
    std = torch.tensor([0.2470, 0.2435, 0.2616]).view(1,3,1,1)
    imgs = (imgs - mean) / std

    # Add trigger
    if corner == 'top_left':
        r_start, c_start = 1, 1
    elif corner == 'top_right':
        r_start, c_start = 1, 32 - 1 - size
    elif corner == 'bottom_left':
        r_start, c_start = 32 - 1 - size, 1
    elif corner == 'bottom_right':
        r_start, c_start = 32 - 1 - size, 32 - 1 - size

    if trigger_type == 'white':
        trigger_val = 1.0  # white in normalized space ~ (1 - mean)/std
        # Actually, white pixel = 255 -> (1.0 - mean)/std
        trigger = torch.ones(3, size, size)
        for ch in range(3):
            trigger[ch] = (1.0 - mean[0,ch,0,0]) / std[0,ch,0,0]
    elif trigger_type == 'checkerboard':
        trigger = torch.zeros(3, size, size)
        for ch in range(3):
            for i in range(size):
                for j in range(size):
                    val = 1.0 if (i+j) % 2 == 0 else 0.0
                    trigger[ch, i, j] = (val - mean[0,ch,0,0]) / std[0,ch,0,0]
    elif trigger_type == 'random':
        trigger = torch.zeros(3, size, size)
        for ch in range(3):
            for i in range(size):
                for j in range(size):
                    val = np.random.randint(0, 2)
                    trigger[ch, i, j] = (val - mean[0,ch,0,0]) / std[0,ch,0,0]

    imgs[:, :, r_start:r_start+size, c_start:c_start+size] = trigger
    return imgs

# Test different trigger configurations
corners = ['top_left', 'top_right', 'bottom_left', 'bottom_right']
trigger_types = ['white', 'checkerboard', 'random']
sizes = [3, 4, 5]

# Let's first just check a few configurations quickly
for corner in corners:
    for ttype in trigger_types:
        for size in sizes:
            imgs = create_triggered_images(ttype, size, corner)
            logits = forward(W, (imgs * 255).byte())  # convert back to uint8
            preds = logits.argmax(dim=1)
            # Check if there's a dominant class
            unique, counts = torch.unique(preds, return_counts=True)
            if counts.max() > 10:  # majority class
                print(f"Corner: {corner}, Type: {ttype}, Size: {size} -> Preds: {dict(zip(unique.tolist(), counts.tolist()))}")

